// Controlled in-memory remote service: shared by isolated browser contexts, no production access.
const records=new Map();
const clientSource=String.raw`export function testMedia(account='owner'){
 const base='/test-media?account='+encodeURIComponent(account);
 const call=async data=>{const r=await fetch(base,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.error);return v;};
 return {list:()=>call({action:'list'}),upload:async(file,meta)=>{const r=await fetch(base+'&upload='+encodeURIComponent(JSON.stringify(meta)),{method:'PUT',body:file});return r.json();},read:id=>Promise.resolve(base+'&file='+encodeURIComponent(id)),file:async id=>(await fetch(base+'&file='+encodeURIComponent(id))).blob(),loadDraft:projectId=>call({action:'load',projectId}),saveDraft:(projectId,manifest,brands,revision)=>call({action:'save',projectId,manifest,brands,revision})};
}`;
function handler(req,res){const url=new URL(req.url,'http://localhost');if(url.pathname==='/test-media-client.js'){res.setHeader('Content-Type','text/javascript');res.end(clientSource);return true;}if(url.pathname!=='/test-media')return false;const key=url.searchParams.get('account');if(!records.has(key))records.set(key,{assets:new Map(),files:new Map(),drafts:new Map()});const state=records.get(key);res.setHeader('Content-Type','application/json');if(url.searchParams.has('file')){const id=url.searchParams.get('file'),file=state.files.get(id);if(!file){res.statusCode=404;res.end('{}');return true;}res.setHeader('Content-Type',state.assets.get(id).mimeType);res.end(file);return true;}const chunks=[];req.on('data',b=>chunks.push(b));req.on('end',()=>{try{const bytes=Buffer.concat(chunks);if(req.method==='PUT'){const m=JSON.parse(url.searchParams.get('upload'));state.files.set(m.id,bytes);state.assets.set(m.id,m);res.end(JSON.stringify(m));return;}const d=JSON.parse(bytes);let result;if(d.action==='list')result=[...state.assets.values()];if(d.action==='load')result=state.drafts.get(d.projectId)||null;if(d.action==='save'){const old=state.drafts.get(d.projectId);if((old?.revision||0)!==d.revision)throw Error('Cloud draft conflict');result={manifest:d.manifest,brands:d.brands,revision:d.revision+1};state.drafts.set(d.projectId,result);}res.end(JSON.stringify(result));}catch(e){res.statusCode=409;res.end(JSON.stringify({error:e.message}));}});return true;}
module.exports={handler};
